// Projektion (identisch zur Erzeugung der Pfade)
const MIN_X = 0.10247908789176777;
const MAX_Y = 1.1559557956214297;
const SCALE = 3514.2500840263947;
const OFF_X = 18.885487460197965;
const OFF_Y = 18.0;

/** Rechnet Breiten-/Längengrad in viewBox-Koordinaten (x, y) um. */
export function geoZuXY(lat: number, lon: number): [number, number] {
  const x = OFF_X + ((lon * Math.PI) / 180 - MIN_X) * SCALE;
  const y = OFF_Y + (MAX_Y - Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360))) * SCALE;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
